<?php
declare(strict_types=1);
require_once __DIR__.'/control-operations.php';

function nodenoControlKolaybiBase(string $environment):string {
 if(!in_array($environment,['sandbox','live'],true))throw new NodenoControlHttpError(422,'environment_invalid');return $environment==='live'?'https://ofis-api.kolaybi.com':'https://ofis-sandbox-api.kolaybi.com';
}
/** Credentials never leave this fixed, verified TLS origin; redirects are forbidden. */
function nodenoControlKolaybiRequest(array $settings,string $method,string $path,array $body=[],?string $token=null):array {
 $allowed=['/kolaybi/v1/access_token','/kolaybi/v1/companies','/kolaybi/v1/invoices','/kolaybi/v1/invoices/e-document/create'];if(!in_array($path,$allowed,true)&&!($method==='GET'&&preg_match('~^/kolaybi/v1/invoices/(?:[1-9][0-9]{0,17}|e-document/view\?uuid=[a-fA-F0-9-]{36}&direction=outbound&output_type=pdf)$~D',$path)))throw new NodenoControlHttpError(422,'provider_endpoint_rejected');$base=nodenoControlKolaybiBase($settings['environment']);if(!function_exists('curl_init'))throw new NodenoControlHttpError(503,'curl_unavailable');$channel=$settings['channel']??'';if(!is_string($channel)||preg_match('/[\r\n]/',$channel)||strlen($channel)>200)throw new NodenoControlHttpError(422,'channel_invalid');$headers=['Accept: application/json','Channel: '.$channel];if($token!==null){if(preg_match('/[\r\n]/',$token))throw new NodenoControlHttpError(502,'provider_response_invalid');$headers[]='Authorization: Bearer '.$token;}$json=$path==='/kolaybi/v1/access_token';$headers[]='Content-Type: '.($json?'application/json':'application/x-www-form-urlencoded');$buffer='';$curl=curl_init($base.$path);
 curl_setopt_array($curl,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>40,(defined('CURLOPT_PROTOCOLS_STR')?constant('CURLOPT_PROTOCOLS_STR'):CURLOPT_PROTOCOLS)=>(defined('CURLOPT_PROTOCOLS_STR')?'HTTPS':CURLPROTO_HTTPS),CURLOPT_WRITEFUNCTION=>static function($ch,$chunk)use(&$buffer){if(strlen($buffer)+strlen($chunk)>2000000)return 0;$buffer.=$chunk;return strlen($chunk);}]);if($method==='POST')curl_setopt($curl,CURLOPT_POSTFIELDS,$json?json_encode($body,JSON_THROW_ON_ERROR):http_build_query($body,'','&',PHP_QUERY_RFC3986));$ok=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);$curl=null;if($ok===false||$status<200||$status>=300)throw new NodenoControlHttpError(502,'provider_request_failed');try{$result=json_decode($buffer,true,64,JSON_THROW_ON_ERROR);}catch(Throwable $e){throw new NodenoControlHttpError(502,'provider_response_invalid');}if(!is_array($result)||isset($result['success'])&&$result['success']===false)throw new NodenoControlHttpError(502,'provider_request_failed');return $result;
}
function nodenoControlKolaybiToken(array $settings):string {$result=nodenoControlKolaybiRequest($settings,'POST','/kolaybi/v1/access_token',['api_key'=>$settings['apiKey']]);$token=$result['data']??null;if(!is_string($token)||strlen($token)<10||strlen($token)>8000)throw new NodenoControlHttpError(502,'provider_token_invalid');return $token;}
function nodenoControlKolaybiItems(array $items,array $mappings,string $policy):array {
 if(!in_array($policy,['vat_included','vat_excluded'],true))throw new NodenoControlHttpError(422,'price_tax_policy_required');$result=[];foreach($items as $item){$mapping=$mappings[$item['productId']]??null;if(!$mapping)throw new NodenoControlHttpError(422,'kolaybi_product_mapping_required');$vat=(int)$mapping['vatRate'];$value=$item['unitPriceMinor']/100;if($policy==='vat_included')$value/=1+$vat/100;$result[]=['product_id'=>$mapping['externalId'],'quantity'=>(string)$item['quantity'],'unit_price'=>number_format($value,6,'.',''),'vat_rate'=>$mapping['vatRate']];}return $result;
}
function nodenoControlKolaybiPdf(array $response):string {
 $data=$response['data']??[];$encoded=$data['src']??null;if(($data['output_type']??'')!=='pdf'||!is_string($encoded)||strlen($encoded)>2000000)throw new NodenoControlHttpError(502,'provider_document_invalid');$bytes=base64_decode($encoded,true);if($bytes===false||!str_starts_with($bytes,'%PDF-'))throw new NodenoControlHttpError(502,'provider_document_invalid');return $bytes;
}
function nodenoControlKolaybiDocument(array $ctx,string $id,string $action):array {
 nodenoControlRequire($ctx,'operations.read');$db=$ctx['db'];$root=$ctx['root'];if(!nodenoControlRead($db,'invoices',$id))throw new NodenoControlHttpError(404,'not_found');$mapping=nodenoControlSetting($db,'kolaybi-document:'.$id,[]);$stored=nodenoControlSetting($db,'integration:kolaybi');if(empty($mapping['externalId']))return ['data'=>$mapping?:['status'=>'not_created']];if(!$stored||$stored['status']!=='connected'||($mapping['environment']??'')!==($stored['environment']??'')||empty($mapping['connectionId'])||!hash_equals((string)($stored['connectionId']??''),$mapping['connectionId']))throw new NodenoControlHttpError(422,'kolaybi_environment_mismatch');$settings=json_decode(nodenoControlDecrypt($root,$stored['encrypted'],'integration:kolaybi'),true);$token=nodenoControlKolaybiToken($settings);
 if($action==='status'){$result=nodenoControlKolaybiRequest($settings,'GET','/kolaybi/v1/invoices/'.rawurlencode((string)$mapping['externalId']),[],$token);$doc=$result['data']??[];if(!is_array($doc))throw new NodenoControlHttpError(502,'provider_response_invalid');$uuid=$doc['uuid']??null;$safe=['status'=>$mapping['status'],'externalId'=>$mapping['externalId'],'environment'=>$mapping['environment'],'connectionId'=>$mapping['connectionId'],'checkedAt'=>time(),'providerStatus'=>is_string($doc['status']??null)?substr($doc['status'],0,100):null,'uuid'=>is_string($uuid)&&preg_match('/^[a-f0-9-]{36}$/Di',$uuid)?$uuid:null];nodenoControlSetSetting($db,'kolaybi-document:'.$id,$safe);return ['data'=>$safe];}
 if($action==='pdf'){if(empty($mapping['uuid']))throw new NodenoControlHttpError(422,'fiscal_document_not_available');$path='/kolaybi/v1/invoices/e-document/view?uuid='.rawurlencode($mapping['uuid']).'&direction=outbound&output_type=pdf';$bytes=nodenoControlKolaybiPdf(nodenoControlKolaybiRequest($settings,'GET',$path,[],$token));nodenoRespond($bytes,200,'application/pdf',['Content-Disposition'=>'attachment; filename="NODENO-fatura.pdf"','Cache-Control'=>'no-store','X-Robots-Tag'=>'noindex,nofollow']);return ['_responded'=>true];}throw new NodenoControlHttpError(404,'action_unknown');
}
function nodenoControlKolaybiInvoice(array $ctx,string $id,string $action,array $body):array {
 $actor=nodenoControlRequire($ctx,'operations.write',true);$db=$ctx['db'];$root=$ctx['root'];$record=nodenoControlRead($db,'invoices',$id);if(!$record||(int)($body['version']??0)!==$record['version'])throw new NodenoControlHttpError(409,'version_conflict');$stored=nodenoControlSetting($db,'integration:kolaybi');if(!$stored||($stored['status']??'')!=='connected')throw new NodenoControlHttpError(422,'kolaybi_not_connected');$settings=json_decode(nodenoControlDecrypt($root,$stored['encrypted'],'integration:kolaybi'),true);$order=nodenoControlRead($db,'orders',$record['data']['orderId']);if(!$order)throw new NodenoControlHttpError(422,'order_unknown');$mapping=nodenoControlSetting($db,'kolaybi-document:'.$id,[]);
 // Real fiscal activation is deferred by the merchant; this route cannot bypass it.
 if($action==='issue')throw new NodenoControlHttpError(422,'fiscal_activation_pending_legal_setup');
 if($action!=='create-draft')throw new NodenoControlHttpError(404,'action_unknown');if($mapping){if(($mapping['environment']??'')!==($stored['environment']??'')||empty($mapping['connectionId'])||!hash_equals((string)($stored['connectionId']??''),$mapping['connectionId']))throw new NodenoControlHttpError(422,'kolaybi_connection_mismatch');return ['data'=>$mapping];}if(empty($record['data']['connectionId'])||!hash_equals((string)($stored['connectionId']??''),$record['data']['connectionId']))throw new NodenoControlHttpError(422,'kolaybi_connection_mismatch');$invoice=$record['data'];if(empty($invoice['contactId'])||empty($invoice['addressId']))throw new NodenoControlHttpError(422,'kolaybi_contact_mapping_required');$products=[];$q=$db->query("SELECT data_json FROM control_records WHERE resource='productMappings'");foreach($q->fetchAll() as $row){$m=json_decode($row['data_json'],true);if(($m['connectionId']??'')===($stored['connectionId']??null))$products[$m['productId']]=$m;}$business=nodenoControlRead($db,'business','default')['data']??[];if($settings['environment']==='live'&&(empty($business['legalName'])||empty($business['taxId'])||empty($business['address'])))throw new NodenoControlHttpError(422,'business_setup_required');$items=nodenoControlKolaybiItems($order['data']['items'],$products,$business['priceTaxPolicy']??'');
 $payload=['contact_id'=>$invoice['contactId'],'address_id'=>$invoice['addressId'],'order_date'=>gmdate('Y-m-d'),'currency'=>'TRY','items'=>$items,'description'=>'NODENO '.$id,'receiver_email'=>$order['data']['email']];$key=(string)($body['idempotencyKey']??'');if(!preg_match('/^[A-Za-z0-9_-]{16,100}$/D',$key))throw new NodenoControlHttpError(422,'idempotency_key_required');
 // Reserve the external command BEFORE network IO. An uncertain timeout is never retried blindly.
 $reserved=nodenoControlTransaction($db,static function()use($db,$id,$stored):bool{if(nodenoControlSetting($db,'kolaybi-document:'.$id))return false;nodenoControlSetSetting($db,'kolaybi-document:'.$id,['status'=>'pending','environment'=>$stored['environment'],'connectionId'=>$stored['connectionId'],'at'=>time()]);return true;});if(!$reserved)return ['data'=>nodenoControlSetting($db,'kolaybi-document:'.$id)];
 try{$result=nodenoControlKolaybiRequest($settings,'POST','/kolaybi/v1/invoices',$payload,nodenoControlKolaybiToken($settings));$externalId=$result['data']['id']??null;if(!is_int($externalId)&&!ctype_digit((string)$externalId))throw new NodenoControlHttpError(502,'provider_document_id_missing');$mapping=['status'=>'draft_created','externalId'=>(string)$externalId,'environment'=>$settings['environment'],'connectionId'=>$stored['connectionId'],'at'=>time()];nodenoControlSetSetting($db,'kolaybi-document:'.$id,$mapping);nodenoControlAudit($db,$root,$actor['id'],'kolaybi-draft','invoices',$id,$mapping);return ['data'=>$mapping];}catch(Throwable $e){nodenoControlSetSetting($db,'kolaybi-document:'.$id,['status'=>'uncertain_reconcile_in_kolaybi','environment'=>$settings['environment'],'connectionId'=>$stored['connectionId'],'at'=>time()]);throw $e;}
}
